<?php declare(strict_types=1);namespace App\Application\Arena\Service;use App\Application\Performance\Port\TransactionManagerInterface;use App\Domain\Arena\Enum\DuelStatus;use App\Domain\Arena\Repository\ArenaPerformanceRecorderInterface;use App\Domain\Arena\Repository\DuelRepositoryInterface;use App\Domain\Arena\Repository\DuelRoundCloserInterface;final class CloseDuelRoundService{public function __construct(private readonly DuelRepositoryInterface $duels,private readonly DuelRoundCloserInterface $closer,private readonly TransactionManagerInterface $transactions,private readonly ?ArenaPerformanceRecorderInterface $performance=null){}public function close(string $duelId,string $userId):bool{return$this->transactions->transactional(function()use($duelId,$userId){$d=$this->duels->findForParticipant($duelId,$userId);if(!$d||$d->status!==DuelStatus::QUESTION_OPEN||$d->deadlineAt===null)throw new \DomainException('Questão não está aberta.');if(!$this->closer->closeIfReady($d->id,$d->currentPosition,$d->deadlineAt))return false;$this->performance?->record($d->id,$d->currentPosition);$d->status=$d->currentPosition>=$d->questionCount?DuelStatus::FINISHED:DuelStatus::QUESTION_RESULT;if($d->status===DuelStatus::FINISHED)$d->finishedAt=new \DateTimeImmutable('now',new \DateTimeZone('UTC'));$this->duels->save($d);return true;});}}
